def run(inputs, row):
    temp = inputs.get('zoneTemp') or []
    sp = inputs.get('zoneSp') or []
    if not temp or not sp:
        return None
    return temp[-1][1] - sp[-1][1]

def run(inputs, row):
    discharge = inputs.get('dischargeTemp') or []
    ret = inputs.get('returnTemp') or []
    if not discharge or not ret:
        return None
    return ret[-1][1] - discharge[-1][1]

def run(inputs, row):
    series = inputs.get('fanStatus') or []
    if not series:
        return None
    active = sum(1 for _, v in series if v == 'active')
    return active / len(series)

def run(inputs, row):
    vals = [s[-1][1] for s in inputs if s]
    return sum(vals) if vals else None
